#!/usr/bin/env sh
# Creates local-dev env files for the docker compose stack. Never overwrites an existing file.
set -eu

root=$(cd "$(dirname "$0")/.." && pwd)
cd "$root"

secret() { openssl rand -hex "$1"; }

render_secret=""

if [ -e .env.local ]; then
  echo ".env.local exists, leaving it alone"
else
  render_secret=$(secret 32)
  cat > .env.local <<EOF
# Generated by \`make setup\` for the local docker compose stack (docker-compose.yml).

NEXT_PUBLIC_SITE_URL=http://localhost:3000
BETTER_AUTH_URL=http://localhost:3000
BETTER_AUTH_SECRET=$(secret 32)
NEXT_PUBLIC_ACCOUNT_SIGNUP_TYPE=enabled

POSTGRES_URL=postgres://tomomai:tomomai@localhost:${POSTGRES_PORT:-5432}/tomomai
REDIS_URL=redis://localhost:${REDIS_PORT:-6379}

# RustFS stands in for R2.
R2_ENDPOINT=http://localhost:${S3_PORT:-9000}
R2_FORCE_PATH_STYLE=true
R2_ACCESS_KEY_ID=tomomai
R2_SECRET_ACCESS_KEY=tomomai-dev-secret
R2_BUCKET=tomomai
NEXT_PUBLIC_R2_URL=http://localhost:${S3_PORT:-9000}/tomomai
NEXT_PUBLIC_R2_URL_CN=http://localhost:${S3_PORT:-9000}/tomomai

TOKEN_SECRET=$(secret 32)
MAIMAI_TOTP_SECRET=$(secret 20)
CRON_SECRET=$(secret 16)
ADMIN_UPDATE_TOKEN=$(secret 16)

# Run apps/render with \`pnpm render:dev\`.
RENDER_TOKEN_SECRET=$render_secret
RENDER_PUBLIC_URL=http://localhost:8080
RENDER_INTERNAL_URL=http://localhost:8080

# Everything below is optional. Uncomment and fill in what you need, see SETUP.md.

# OAuth sign-in. The dev-only anonymous sign-in works without them.
# Discord redirect URI: http://localhost:3000/api/auth/callback/discord
DISCORD_CLIENT_ID=
DISCORD_CLIENT_SECRET=
TWITTER_CLIENT_ID=
TWITTER_CLIENT_SECRET=

# Discord bot (slash commands). Run \`make discord-tunnel\` for a public
# interactions endpoint and \`make discord-register\` for the commands.
# NEXT_PUBLIC_DISCORD_APPLICATION_ID=
# DISCORD_PUBLIC_KEY=
# DISCORD_BOT_TOKEN=
# DISCORD_UPDATE_WEBHOOK=
# DISCORD_UPDATE_WEBHOOK_NOTICE=

# Captcha. ALTCHA falls back to a dev key, Turnstile is off unless both keys are set.
# ALTCHA_HMAC_KEY=
# NEXT_PUBLIC_TURNSTILE_SITE_KEY=
# TURNSTILE_SECRET_KEY=
# TURNSTILE_EXPECTED_HOSTNAME=localhost

# App configuration
# NEXT_PUBLIC_ENABLED_REGIONS=intl,jp
# TRUSTED_ORIGINS=
# AUTH_COOKIE_DOMAIN=
# DEMO_FETCH=true

# Vercel Edge Config feature flags. Defaults apply when unset.
# EDGE_CONFIG=
# FLAGS_SECRET=

# Userscript import flow (an OAuth app from /settings/developer).
# USERSCRIPT_CLIENT_ID=
# USERSCRIPT_CLIENT_SECRET=

# AI event fetching
# OPENROUTER_KEY=
# AI_MODEL=google/gemini-3.1-flash-lite-preview

# China fetcher providers
# DIVINGFISH_DEV_TOKEN=
# LXNS_CLIENT_ID=
# LXNS_CLIENT_SECRET=
# LXNS_REDIRECT_URI=
# CN_PROXY_HOST=
# CN_PROXY_PORT=2560
# CN_PROXY_TOKEN_SECRET=
# DEBUG_CN_FETCH=1

# Logging
# LOG_LEVEL=trace
# DEV_LOGTAIL_SOURCE_TOKEN=
# INGESTING_HOST=
# AXIOM_TOKEN=
# AXIOM_DATASET=
# AXIOM_URL=api.axiom.co

# Source site for \`make seed\`.
# SEED_SOURCE_URL=https://www.tomomai.lol
EOF
  echo "created .env.local"
fi

if [ -e apps/main/.env.local ] || [ -L apps/main/.env.local ]; then
  echo "apps/main/.env.local exists, leaving it alone"
else
  ln -s ../../.env.local apps/main/.env.local
  echo "linked apps/main/.env.local -> ../../.env.local"
fi

if [ -e apps/render/.env.local ]; then
  echo "apps/render/.env.local exists, leaving it alone"
  if [ -n "$render_secret" ]; then
    echo "  warning: set RENDER_TOKEN_SECRET in apps/render/.env.local to match .env.local"
  fi
else
  root_existed=false
  if [ -z "$render_secret" ]; then
    root_existed=true
    render_secret=$(secret 32)
  fi
  sed \
    -e "s|^RENDER_TOKEN_SECRET=.*|RENDER_TOKEN_SECRET=$render_secret|" \
    -e "s|^# CATALOG_URL=.*|CATALOG_URL=http://localhost:3000|" \
    -e "s|^NEXT_PUBLIC_R2_URL=.*|NEXT_PUBLIC_R2_URL=http://localhost:${S3_PORT:-9000}/tomomai|" \
    -e "s|^NEXT_PUBLIC_R2_URL_CN=.*|NEXT_PUBLIC_R2_URL_CN=http://localhost:${S3_PORT:-9000}/tomomai|" \
    apps/render/.env.example > apps/render/.env.local
  echo "created apps/render/.env.local"
  if [ "$root_existed" = true ]; then
    echo "  warning: set RENDER_TOKEN_SECRET in .env.local to match apps/render/.env.local"
  fi
fi

guess_db_url="postgres://tomomai:tomomai@localhost:${POSTGRES_PORT:-5432}/guess"

if [ -e apps/guess/.env.local ]; then
  echo "apps/guess/.env.local exists, leaving it alone"
  if ! grep -q '^POSTGRES_URL=' apps/guess/.env.local; then
    echo "  hint: add POSTGRES_URL=$guess_db_url to freeze daily puzzles locally"
  fi
else
  cat > apps/guess/.env.local <<EOF
# Generated by \`make setup\` for the local docker compose stack (docker-compose.yml).

GUESS_DAILY_SECRET=$(secret 32)
TOMOMAI_API_URL=http://localhost:3000
NEXT_PUBLIC_SITE_URL=http://localhost:3001

# Separate \`guess\` database in the compose Postgres, created by \`make migrate\`.
POSTGRES_URL=$guess_db_url
REDIS_URL=redis://localhost:${REDIS_PORT:-6379}

# Optional "Sign in with tomomai": create an OAuth app at
# http://localhost:3000/settings/developer with the Account info scope and
# http://localhost:3001/api/auth/callback as its redirect URI.
TOMOMAI_OAUTH_CLIENT_ID=
TOMOMAI_OAUTH_CLIENT_SECRET=
EOF
  echo "created apps/guess/.env.local"
fi
